        {
            var vp = viewProjection.ToNative();
            var cam = cameraPositionWorld.ToNative();
            var lightDir = lightDirectionWorld.ToNative();
            var lightCol = lightColor.ToNative();
            var amb = ambientColor.ToNative();
            var pRight = particleCameraRight.ToNative();
            var pUp = particleCameraUp.ToNative();
            Native.spark_scene_submit_terrain_demo_from_world(
                InteropPtr.World(Handle),
                InteropPtr.Context(context.Handle),
                &vp,
                &cam,
                &lightDir,
                &lightCol,
                lightIntensity,
                &amb,
                enableParticles ? 1 : 0,
                &pRight,
                &pUp,
                sceneTimeSeconds,
                spriteSortMode,
                ssaoEnabled ? 1 : 0);
