public static class DemoScreenRay
{
    public static bool TryTerrainScreenToWorldRay(
        int fbW,
        int fbH,
        float px,
        float py,
        in Matrix4 invViewProj,
        out Vector3 origin,
        out Vector3 direction)
    {
        origin = default;
        direction = default;
        unsafe
        {
            var inv = invViewProj.ToNative();
            var ro = new SparkVector3();
            var rd = new SparkVector3();
            int ok = Native.spark_demo_terrain_screen_to_world_ray(fbW, fbH, px, py, &inv, &ro, &rd);
            if (ok == 0)
            {
                return false;
            }

            origin = Vector3.FromNative(ro);
            direction = Vector3.FromNative(rd);
            return true;
        }
    }
}
